import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const l="/bzygq/assets/quesion_imgs_327b299ee39a4302b9314afd5ab2aa07.gWgy-Fz_.png",r="/bzygq/assets/quesion_imgs_dc9d1c55d795412ba940ab4c2a173411.BsH04BVG.png",o="/bzygq/assets/quesion_imgs_365046c1cd804e438b18ea91f14c2285.ew5Qxose.png",B=JSON.parse('{"title":"什么是类比推理？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/3.类比推理.md","filePath":"行测/逻辑推理/3.类比推理.md","lastUpdated":1788883925000}'),s={name:"行测/逻辑推理/3.类比推理.md"};function n(_,p,c,d,h,u){return e(),t("div",null,[...p[0]||(p[0]=[i('<h1 id="什么是类比推理" tabindex="-1">什么是类比推理？ <a class="header-anchor" href="#什么是类比推理" aria-label="Permalink to &quot;什么是类比推理？&quot;">​</a></h1><p>行测（行政职业能力测验）中的类比推理题是一种常见的题型，主要考察考生的语言理解能力、逻辑思维能力和知识面。这类题目通常给出一对或多对词语，要求考生找出它们之间的关系，并根据这种关系选择出与之相对应的一对词语。题目形式如下：</p><p>例1：莲蓬对于()相当于()对于葛根</p><p>A.荷叶：葛藤</p><p>B.荷花：葛粉</p><p>C.喜爱：纠缠</p><p>D.荷塘：山岗</p><p>例2：衣服：衣领：衣袖</p><p>A.鱼：鱼头：鱼尾</p><p>B.警察：刑警：交警</p><p>C.音乐：古典音乐：流行音乐</p><p>D.人民币：美元：韩币</p><p>简单来说，类比推理就是给你一系列根据某种规律组织在一起的题目，让你根据规律选出答案。这种题目看似简单，但是倘若不掌握一定方法，也是很容易出错的。</p><h1 id="思维导图" tabindex="-1">思维导图 <a class="header-anchor" href="#思维导图" aria-label="Permalink to &quot;思维导图&quot;">​</a></h1><p><img src="'+l+'" alt=""></p><h1 id="语义关系" tabindex="-1">语义关系 <a class="header-anchor" href="#语义关系" aria-label="Permalink to &quot;语义关系&quot;">​</a></h1><p>【语义关系是指词语含义之间的关系，正确理解词语含义是做该题型的基础常考的语义关系主要分为三种: (1)近义词:词语含义相近，例如水滴石穿、绳锯木断； (2)反义词:词语含义相反，例如见异思迁、忠贞不二； (3)比喻义、象征义:通过对某些具体事物比喻或象征某些抽象意义，例如荆棘比喻困难，玫瑰象征爱情。注:比喻、象征二者之间既存在差异也有相同之处，考试一般不需要进行区分 】</p><p>例 1：(2018 国考)羔羊跪乳:乌鸦反哺()</p><p>A.昙花一现:惊鸿一瞥</p><p>B.魂不附体:失魂落魄</p><p>C.锋芒毕露:锐不可当</p><p>D.朽木难雕:孺子可教</p><p>解析：第一步:判断题干词语间逻辑关系。“羔羊跪乳”和“乌鸦反哺“出自古训《增广贤文》，原文是&quot;羊有跪乳之恩，鸦有反哺之义”。“羔羊跪乳”和“乌鸦反哺”都有感恩父母、奉养长辈的意思，二者是近义关系。第二步:判断选项词语间逻辑关系。A项“昙花一现”指美好的事物出现的时间很短&quot;惊鸿一瞥”的意思是只是匆匆看了一眼，却给人留下强烈、深刻的印象，二者不是近义关系，与题干逻辑关系不一致，排除。B项:“魂不附体”的意思是灵魂离开了身体，形容极端惊慌，“失魂落魄”的意思是魂魄离开身体，也是形容惊慌忧虑，二者是近义关系，与题干逻辑关系一致，当选。C项:&quot;锋芒毕露”的意思是刀锋和矛尖都露出来，比喻锐气和才干全都显露、透露出来，“锐不可当”形容勇往直前的气势，不可抵挡，二者不是近义关系，与题干逻辑关系不一致，排除。D项:“朽木难雕”是指腐烂的木头很难雕刻，比喻人不可造就或事情无法挽救，“孺子可教”本义为小孩子是可以教诲的，后形容年轻人有培养前途，二者是反义关系，与题干逻辑关系不一致，排除。故正确答案为 B。</p><h2 id="包容关系" tabindex="-1">包容关系 <a class="header-anchor" href="#包容关系" aria-label="Permalink to &quot;包容关系&quot;">​</a></h2><p>【包容关系是指两个词语概念之间一个范围大，一个范围小，小概念完全被包含在大概念之中，例如男人和人，桌面和桌子。包容关系可以分为以下两类:</p><ul><li>种属关系：即 A是B的一种，如柳树和树--柳树是树的一种。</li><li>组成关系：即A是B的一个组成部分，如轮胎和汽车，轮胎是汽车的组成部分组成与种属的区别在于，A、B为种属关系，造句子可以造成A是B，比如柳树是树;但组成关系不可以，比如不能说轮胎是汽车。】</li></ul><p>例 1：电脑:设备</p><p>A. 广播:传媒</p><p>B.颜料:绘画</p><p>C.文言:白话</p><p>D.能源:煤炭</p><p>解析：第一步:判断题干词语间逻辑关系。电脑是一种设备，二者是种属关系。第二步:判断选项词语间逻辑关系。A项:传媒指传播媒介，特指报纸、广播、电视、网络等各种新闻工具，广播是一种传媒，二者是种属关系，与题干逻辑关系一致，当选:B项:颜料是绘画所用的材料，二者不是种属关系，与题干逻辑关系不一致，排除;C项:文言和白话为汉语书面语的两种形式，二者是并列关系而非种属关系，与题于逻辑关系不一致，排除:D 项:煤炭是一种能源，二者是种属关系，但两词顺序与题干相反，与题干逻辑关系不一致，排除。故正确答案为 A。</p><h1 id="对应关系" tabindex="-1">对应关系 <a class="header-anchor" href="#对应关系" aria-label="Permalink to &quot;对应关系&quot;">​</a></h1><p>【对应关系是指一定范围事件包含的各词语要素之间构成的相互对应，包括物品、职业地点、原因、结果、方式、行为、工具、功能等多种对应。例如教师和教室是职业和地点的对应，医生和手术刀是职业和工具的对应。常考的对应关系有5种:</p><ul><li>配套使用:如牙刷与牙膏、螺丝与螺母。</li><li>物品与原材料、制作工艺: 如家具与木材、手与打唐。</li><li>物品与功能: 如手机与沟通、汽车与运输。</li><li>属性关系: 如盐与咸、叶与绿。</li><li>因果关系: 如下雨与地湿、淋雨与感冒】</li></ul><p>例 1：(2020 山西)羊:羊奶:腥膻</p><p>A.蚕:蚕丝:雪自</p><p>B.蜘蛛:蛛丝:粘缚</p><p>C、蜂:蜂蜜:甘甜</p><p>D.雨燕:燕窝:营养</p><p>解析：第一步:判断题干词语间逻辑关系。羊奶是羊的分泌物，羊奶的属性是腥膻，腥膻是必然属性，且是一种味道。第二步:判断选项词语间逻辑关系。</p><p>A项:蚕丝是蚕的分泌物，雪白虽然是蚕丝的属性，但是雪白不是必然属性，也不是一种味道，与题干逻辑关系不一致，排除;</p><p>B项:蛛丝是蜘蛛的分泌物，但是粘缚并非蛛丝的属性，而是功能，与题干逻关系不一致，排除;</p><p>C项:蜂蜜是蜂的分泌物，蜂蜜的属性是甘甜，甘甜是必然属性，且是一种味道，与题干逻辑关系一致，当选:</p><p>D项:燕窝是雨燕科几种金丝燕分泌的唾液及其绒羽混合粘结所成的巢穴，并非是单纯的分泌物，与题干逻辑关系不一致，排除。故正确答案为 C。</p><h1 id="交叉关系" tabindex="-1">交叉关系 <a class="header-anchor" href="#交叉关系" aria-label="Permalink to &quot;交叉关系&quot;">​</a></h1><p>当两个集合的范围中有交叉的时候，就存在交叉关系，比如学生和党员之间的关系有的学生是党员，有的党员是学生，这两个集合之间存在着交叉的关系，如下图:</p><p><img src="'+r+'" alt=""></p><p>例 1：(2023 国考)铜镜:化妆镜</p><p>A. 门帘:纱帘</p><p>B.木碗:汤碗</p><p>C.金簪:发簪</p><p>D.瓷瓶:古瓶</p><p>解析：第一步:判断题干词语间逻辑关系。铜镜一般是指由含锡量较高的青铜铸造的镜子，化妆镜一般指专门用于化妆的镜子。有的铜镜是化妆镜，有的铜镜不是化妆镜，有的化妆镜是铜镜，有的化妆镜不是铜镜，二者为交叉关系，且前者是根据材质命名，后者是根据功能命名</p><p>第二步:判断选项词语间逻辑关系。A项:有的门帘是纱帘，有的门帘不是纱帘，有的纱帘是门帘，有的纱帘不是门帘二者为交叉关系，但前者是根据悬挂的位置命名，与题干逻关系不一致，排除;B项:有的木碗是汤碗，有的木碗不是汤碗，有的汤是木碗，有的汤碗不是木碗二者为交叉关系，且前者是根据材质命名，后者是根据功能命名，与题干逻关系一致当选:C项:金簪是发簪的一种，二者为种属关系，与干逻辑关系不一致，排除;D项:古瓶可指古董瓶子或古代的瓶子，有的瓷瓶是古瓶，有的瓷瓶不是古瓶，有的古瓶是瓷瓶，有的古瓶不是瓷瓶，二者为交叉关系，但后者是根据历史时代命名，与题干逻辑关系不一致，排除。故正确答案为 B.</p><h1 id="并列关系" tabindex="-1">并列关系 <a class="header-anchor" href="#并列关系" aria-label="Permalink to &quot;并列关系&quot;">​</a></h1><p>并列关系是指两个词语概念处于同一个级别上，但又彼此不包含，如植物与动物、火星与地球。并列关系可以分为以下两种</p><p><img src="'+o+'" alt=""></p><ul><li><p>矛盾关系：矛盾是指非A即 B，没有第三种情况存在，如生与死、错与对，除了A和 B，不存在其他情况。公务员考试中，经常考的矛盾关系包括:男与女，生与死，开与关，动与静，曲与直。</p></li><li><p>反对关系：反对是指除了A和B以外，还有其他情况存在，如黑色与白色，颜色除了黑和白，还有红、黄、蓝等多种颜色。 |</p></li></ul><p>注:并列关系一般要求同级井列，如广东和南京不是并列关系，广东是省级，而南京是市级。而且两个词语应该明显属于同一事物的集合，如苹果与香蕉明显属于水果这一集合，但计算机与菜刀，不属于同一集合，一般不认为是并列关系。</p><p>例 1：(2023 国考)片剂:散剂:气雾剂</p><p>A.边塞诗:山水诗:抒情诗</p><p>B.口头契约:君子协定:书面协议</p><p>C，泉水:湖水:天然水</p><p>D，头部理疗:腰部理疗:腿部理疗</p><p>解析：第一步:判断题干词语间逻辑关系片剂是药物与辅料均匀混合后压制而成的片状或异形片状的固体制剂，散剂是指药物或与适宜的辅料经粉碎、均匀混合制成的干燥粉末状制剂，气雾剂是指药物和抛射剂共同封装于带有阀门的耐压容器中，使用时借抛射剂气化所产生的压力，定量或非定量地将药物以雾状喷出的制剂，三者是根据药物的剂型划分的，为并列关系中的<strong>反对关系</strong>，第二步:判断选项词语间逻辑关系。</p><p>A项:边寨诗是以边疆地区军民生活和自然风光为题材的诗，山水诗是描写山水风景的诗，抒情诗是抒发诗人思想感情的诗，三者互为交叉关系，与干逻关系不一致，排除;</p><p>B项:口头契约是通过口头达成的契约，君子协定是双方不经过书面签字，只以口头承诺或交换函件而订立的协定，有的口头契约是君子协定，有的口头契约不是君子协定，有的君子协定是口头契约，有的君子协定不是口头契约，二者为交叉关系，与题干逻辑关系不一致，排除;</p><p>C项:泉水是天然水，二者为种属关系:湖水是天然水，二者为种属关系，与题干逻辑关系不一致，排除;</p><p>D项:头部理疗、腰部理疗和腿部理疗是根据理疗的身体部位划分的，三者为并列关系中的反对关系，与题干逻辑关系一致，当选。故正确答案为D.</p>',70)])])}const b=a(s,[["render",n]]);export{B as __pageData,b as default};
